import os,tempfile,shutil,base64,subprocess,json
root=tempfile.mkdtemp(prefix="yi4k-diag-check-",dir="/tmp")
try:
 worker=base64.b64decode('').replace("/tmp/SD0/",root+"/")
 autoexec=base64.b64decode('')
 open(root+"/autoexec.ash","wb").write(autoexec)
 open(root+"/yi4k_diag_0123456789ab_fingerprint.bin","wb").write(base64.b64decode("AwCg4R7/L+E="))
 wp=root+"/worker.py"
 open(wp,"wb").write(worker)
 subprocess.check_call(["python","-B",wp,"claim"])
 assert os.path.isdir(root+"/yi4k_diag_0123456789ab_ready")
 assert os.path.isfile(root+"/autoexec.ash")
 subprocess.check_call(["python","-B",wp,"done"])
 assert os.path.isfile(root+"/yi4k_diag_0123456789ab_done.json")
 subprocess.check_call(["python","-B",wp,"claim"])
 assert not os.path.lexists(root+"/yi4k_diag_0123456789ab_ready")
 print("YI_WORKER_CHECK "+json.dumps({"python2_runtime":True,"script_preserved":True,"second_claim_disarmed":True,"done_persisted":True}))
finally:
 shutil.rmtree(root)
